-- PostgreSQL 16+, warehouse technical baseline v0.3. All weights in kg; dimensions in metres.
BEGIN;
CREATE TABLE IF NOT EXISTS tenants(id BIGSERIAL PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS users_app(id BIGSERIAL PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('ADMIN','WAREHOUSE','TENANT')), tenant_id BIGINT REFERENCES tenants(id), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS racks(code INT PRIMARY KEY CHECK(code BETWEEN 101 AND 124), physical_order INT NOT NULL UNIQUE CHECK(physical_order BETWEEN 1 AND 24), group_no INT, back_to_back_with INT REFERENCES racks(code));
CREATE TABLE IF NOT EXISTS bays(id BIGSERIAL PRIMARY KEY, rack_code INT NOT NULL REFERENCES racks(code), bay_no INT NOT NULL CHECK(bay_no BETWEEN 1 AND 84), status TEXT NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN ('AVAILABLE','BLOCKED','MAINTENANCE')), UNIQUE(rack_code,bay_no));
CREATE TABLE IF NOT EXISTS rack_slots(id BIGSERIAL PRIMARY KEY, bay_id BIGINT NOT NULL REFERENCES bays(id), level_no INT NOT NULL CHECK(level_no BETWEEN 1 AND 6), slot_code CHAR(1) NOT NULL CHECK(slot_code IN ('A','B','C')), blocked BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(bay_id,level_no,slot_code));
CREATE TABLE IF NOT EXISTS leases(id BIGSERIAL PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenants(id), area_m2 NUMERIC(12,2) NOT NULL CHECK(area_m2>0), planned_bay_count INT NOT NULL CHECK(planned_bay_count>0), status TEXT NOT NULL CHECK(status IN ('DRAFT','ACTIVE','CLOSED')) DEFAULT 'DRAFT', start_at TIMESTAMPTZ NOT NULL DEFAULT now(), end_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bay_assignments(id BIGSERIAL PRIMARY KEY, lease_id BIGINT NOT NULL REFERENCES leases(id), bay_id BIGINT NOT NULL REFERENCES bays(id), status TEXT NOT NULL CHECK(status IN ('ACTIVE','RELEASED')) DEFAULT 'ACTIVE', assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(), released_at TIMESTAMPTZ, UNIQUE(lease_id,bay_id));
-- A bay may be actively assigned to ONE tenant/lease only.
CREATE UNIQUE INDEX IF NOT EXISTS ux_active_bay_assignment ON bay_assignments(bay_id) WHERE status='ACTIVE';
CREATE TABLE IF NOT EXISTS skus(id BIGSERIAL PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenants(id), code TEXT NOT NULL, name TEXT NOT NULL, category TEXT, case_length_m NUMERIC(10,4) NOT NULL CHECK(case_length_m>0), case_width_m NUMERIC(10,4) NOT NULL CHECK(case_width_m>0), case_height_m NUMERIC(10,4) NOT NULL CHECK(case_height_m>0), case_gross_kg NUMERIC(12,3) NOT NULL CHECK(case_gross_kg>0), UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS inbound_orders(id BIGSERIAL PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenants(id), source TEXT NOT NULL CHECK(source IN ('EXCEL','MANUAL')), status TEXT NOT NULL CHECK(status IN ('DRAFT','PROPOSED','CONFIRMED','PARTIAL','CANCELLED')) DEFAULT 'DRAFT', created_by BIGINT REFERENCES users_app(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), confirmed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS inbound_lines(id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES inbound_orders(id), sku_id BIGINT NOT NULL REFERENCES skus(id), case_count INT NOT NULL CHECK(case_count>0));
CREATE TABLE IF NOT EXISTS pallets(id BIGSERIAL PRIMARY KEY, pallet_code TEXT UNIQUE NOT NULL, tenant_id BIGINT NOT NULL REFERENCES tenants(id), sku_id BIGINT NOT NULL REFERENCES skus(id), inbound_line_id BIGINT REFERENCES inbound_lines(id), pallet_type TEXT NOT NULL CHECK(pallet_type IN ('SINGLE','DOUBLE','WOOD','OVERSIZE')), case_count INT NOT NULL CHECK(case_count>0), cargo_weight_kg NUMERIC(12,3) NOT NULL CHECK(cargo_weight_kg>0), status TEXT NOT NULL CHECK(status IN ('PLANNED','STORED','OUTBOUND','FLOOR')) DEFAULT 'PLANNED');
CREATE TABLE IF NOT EXISTS pallet_placements(id BIGSERIAL PRIMARY KEY, pallet_id BIGINT NOT NULL REFERENCES pallets(id), bay_id BIGINT NOT NULL REFERENCES bays(id), level_no INT NOT NULL CHECK(level_no BETWEEN 1 AND 6), status TEXT NOT NULL CHECK(status IN ('ACTIVE','RELEASED')) DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), released_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS ux_active_pallet_placement ON pallet_placements(pallet_id) WHERE status='ACTIVE';
CREATE TABLE IF NOT EXISTS occupied_slots(placement_id BIGINT NOT NULL REFERENCES pallet_placements(id) ON DELETE CASCADE, slot_id BIGINT NOT NULL REFERENCES rack_slots(id), PRIMARY KEY(placement_id,slot_id), UNIQUE(slot_id));
-- Only ACTIVE placements should hold occupied_slots; application transaction deletes occupied_slots before release.
CREATE TABLE IF NOT EXISTS proposals(id UUID PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenants(id), kind TEXT NOT NULL CHECK(kind IN ('LEASE','PALLET')), status TEXT NOT NULL CHECK(status IN ('PENDING','CONFIRMED','EXPIRED','CANCELLED')), payload JSONB NOT NULL, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users_app(id), tenant_id BIGINT REFERENCES tenants(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, details JSONB, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_bay_rack_no ON bays(rack_code,bay_no);
CREATE INDEX IF NOT EXISTS ix_slot_lookup ON rack_slots(bay_id,level_no,slot_code);
CREATE INDEX IF NOT EXISTS ix_audit_tenant_time ON audit_events(tenant_id,occurred_at DESC);
COMMIT;
